--
-- Table structure for table `leaves`
--

DROP TABLE IF EXISTS `leaves`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `leaves` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` bigint unsigned NOT NULL,
  `leave_duration_id` bigint unsigned NOT NULL,
  `from` date NOT NULL,
  `to` date NOT NULL,
  `leave_type_id` bigint unsigned NOT NULL,
  `use_confessionnels` tinyint(1) NOT NULL DEFAULT '0',
  `mix_of_leaves` tinyint(1) DEFAULT '0',
  `travelling` tinyint(1) NOT NULL DEFAULT '0',
  `attachment_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date_of_submission` date NOT NULL DEFAULT '2023-01-27',
  `substitute_employee_id` bigint unsigned DEFAULT NULL,
  `disabled_dates` text COLLATE utf8mb4_unicode_ci,
  `leave_status` int NOT NULL DEFAULT '0',
  `processing_officer_role` bigint unsigned DEFAULT NULL,
  `rejected_by` bigint unsigned DEFAULT NULL,
  `cancellation_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `leaves_employee_id_foreign` (`employee_id`),
  KEY `leaves_leave_type_id_foreign` (`leave_type_id`),
  KEY `leaves_processing_officer_role_foreign` (`processing_officer_role`),
  KEY `leaves_substitute_employee_id_foreign` (`substitute_employee_id`),
  KEY `leaves_leave_duration_id_foreign` (`leave_duration_id`),
  KEY `leaves_rejected_by_foreign` (`rejected_by`),
  CONSTRAINT `leaves_employee_id_foreign` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `leaves_leave_duration_id_foreign` FOREIGN KEY (`leave_duration_id`) REFERENCES `leave_durations` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `leaves_leave_type_id_foreign` FOREIGN KEY (`leave_type_id`) REFERENCES `leave_types` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `leaves_processing_officer_role_foreign` FOREIGN KEY (`processing_officer_role`) REFERENCES `roles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `leaves_rejected_by_foreign` FOREIGN KEY (`rejected_by`) REFERENCES `employees` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `leaves_substitute_employee_id_foreign` FOREIGN KEY (`substitute_employee_id`) REFERENCES `employees` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3636 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

