INSERT INTO `notifications_groups` VALUES (3,'Liquidation congé annuel 2022','Attention : la date limite pour l’épuisement du congé annuel de 2022 est fixée au 30 avril 2023, sauf dérogation accordée','2023-04-06 07:57:29','2023-04-06 07:57:29'),(4,'Autorisation spéciale d’absence','Comme communiqué par la Direction le 15/10/2024, 5 jours d’autorisation spéciale d’absence ont été rajoutés à votre solde de congé annuel. Ces 5 jours supplémentaires sont valables pour les 6 prochains mois soit jusqu’au 11 avril 2025.','2024-10-17 12:09:08','2024-10-17 12:09:08'),(5,'Intégration du calendrier des jours fériés 2025','Merci de bien vouloir noter que le calendrier des jours fériés et des jours confessionnels 2025 a été intégré dans Phare.','2024-12-05 10:48:49','2024-12-05 10:48:49'),(8,'Nouveau jour confessionnel rajouté - 10/02/2025','A la suite d\'une note officielle émise ce jour, le 10/02/2025 est un jour confessionnel rajouté à la liste et qui correspond à Saint Maron','2025-02-03 10:36:48','2025-02-03 10:36:48'),(9,'Nouveau jour confessionnel rajouté - 10/02/2025','A la suite d\'une note officielle émise ce jour, le 10/02/2025 est un jour confessionnel rajouté à la liste et qui correspond à Saint Maron','2025-02-03 10:36:48','2025-02-03 10:36:48'),(10,'Eid el Fitr','Rajout du 01/04/2025 comme jour confessionnel.','2025-03-26 15:21:04','2025-03-26 15:21:04'),(11,'Rajout d\'un jour confessionnel - 18/04/2025','A la suite d\'une note officielle émise ce jour, le 18/04/2025 est un jour confessionnel rajouté à la liste et qui correspond à Vendredi Saint','2025-04-03 14:45:44','2025-04-03 14:45:44');
